483-    // An attempt's declaration as its player writes it, whole.
   * after the connection, so the result can offer to add them as a friend.
   */
  public readonly peer = this.peerState.asReadonly();
  public readonly events$: Observable<OnlineEvent> = this.events.asObservable();

  /** True where online matches can be played: with the cloud and WebRTC. */
  public get available(): boolean {
    return this.wire.supported() && this.cloud.rooms() !== null;
  }

  /**
   * Opens a room and waits for a guest. `onCode` hears the room's code as
   * soon as it is open - to challenge a friend with it, or hand it to a
   * player waiting in the matchmaking queue.
   */
  public async host(
    options: { auto?: boolean; onCode?: (code: string) => void } = {}
  ): Promise<void> {
    const rooms = this.cloud.rooms();
    if (rooms === null) {
      return;
    }
    const attempt = this.restart({
      phase: 'opening',
      role: 'host',
      auto: options.auto ?? false,
    });
    try {
      const { link, offer } = await this.wire.offer();
      if (!this.adopt(link, attempt)) {
        return;
      }
      const room = await rooms.open(offer);
      if (attempt !== this.attempt) {
        room.close();
        return;
      }
      this.room = room;
      this.update({ phase: 'waiting', code: room.code });
      options.onCode?.(room.code);
      const answer = await room.answer;
      if (attempt !== this.attempt) {
        return;
      }
      this.update({ phase: 'connecting' });
      await link.accept(answer);
      await link.opened;
      // Taken: nobody else may join it, and the stub names who played -
      // what the functions bind the room's replays to (ADR 0011). The
      // match goes on without it; its uploads would be refused.
      this.room = null;
      if (attempt === this.attempt) {
        room.take().catch((error: unknown) => {
          console.warn('The room could not be taken', error);
        });
      }
    } catch (error) {
      this.fail(attempt, error);
    }
  }

  /** Joins the room under the code a player typed in. */
  public async join(
    typed: string,
    options: { auto?: boolean } = {}
  ): Promise<void> {
    const rooms = this.cloud.rooms();
    const code = normalizeRoomCode(typed);
    if (rooms === null) {
      return;
    }
    if (code === null) {
      this.update({ notice: { key: 'online.notices.badCode' } });
      return;
    }
    const attempt = this.restart({
      phase: 'connecting',
      role: 'guest',
      code,
      auto: options.auto ?? false,
    });
    try {
      const room = await rooms.join(code);
      if (attempt !== this.attempt) {
        return;
      }
      if (room === null) {
        this.endWith(attempt, { key: 'online.notices.noRoom' });
        return;
      }
      const { link, answer } = await this.wire.answer(room.offer);
      if (!this.adopt(link, attempt)) {
        return;
      }
      await room.answer(answer);
      await link.opened;
    } catch (error) {
      if (errorCode(error) === 'permission-denied') {
        // Another guest answered the room first.
        this.endWith(attempt, { key: 'online.notices.taken' });
        return;
      }
      this.fail(attempt, error);
    }
  }

  /** Leaves the room or the match, telling the other device. */
  public leave(): void {
    this.send({ k: 'bye' });
    this.restart(IDLE_LOBBY);
  }

  /** The host shares the setup of the next match with the guest. */
  public share(setup: OnlineSetup): void {
    if (this.lobby().role === 'host') {
      this.send({ k: 'setup', ...setup });
    }
  }

  /**
   * The guest tells the host its own colours, which the host makes the
   * match's pair from. The guest plays the pair the host sends back.
   */
  public offerColors(colors: [string, string]): void {
    if (this.lobby().role === 'guest') {
      this.send({ k: 'colors', colors });
    }
  }

  /**
   * The host starts a match: tells the guest, and returns the lockstep to
   * play it with. Null while no guest is connected.
   */
  public startMatch(start: OnlineStart): Lockstep | null {
    if (this.lobby().role !== 'host' || this.lobby().phase !== 'connected') {
      return null;
    }
    this.match++;
    this.send({ k: 'start', n: this.match, ...start });
    this.lockstep = this.newLockstep(0);
    return this.lockstep;
  }

  /**
   * The ruleset the next match plays by: `gpu-int` when both devices
   * offered it in their hellos, `cpu` else (ADR 0015) - the host starts it,
   * the guest checks it. A device whose GPU failed since plays its
   * `gpu-int` matches on `intSimulation`, so the ruleset still holds.
   */
  public agreedRuleset(): Ruleset {
    return agreedRuleset(this.ownOffers, this.peerOffers);
  }

  /**
   * The room of the match under way and its number there - with the seed,
   * what its replay's id is made of (ADR 0011). Null before the first
   * match of a room.
   */
  public matchRef(): OnlineMatchRef | null {
    const { code } = this.lobby();
    return code === null || this.match === 0
      ? null
      : { roomCode: code, n: this.match };
  }

  /**
   * The guest's game takes the match the host started - null when none
   * waits.
   */
  public takeStart(): { start: OnlineStart; lockstep: Lockstep } | null {
    const pending = this.pendingStart;
    this.pendingStart = null;
    return pending;
  }

  /**
   * Lets go of whatever was under way and sets the lobby to `lobby` -
   * telling the game, for `reason`, if it was connected.
   */
  private restart(
    lobby: Partial<OnlineLobby>,
    reason: OnlineEnd = 'left'
  ): number {
    const wasConnected = this.greeted;
    this.attempt++;
    this.room?.close();
    this.room = null;
    const link = this.link;
    this.link = null;
    link?.close();
    this.lockstep = null;
    this.pendingStart = null;
    this.greeted = false;
    this.ownOffers = ['cpu'];
    this.peerOffers = ['cpu'];
    this.lobbyState.set({ ...IDLE_LOBBY, ...lobby });
    if (wasConnected) {
      this.events.next({ type: 'ended', reason });
    }
    return this.attempt;
  }

  /** Takes the link of an attempt - false when the attempt is over. */
  private adopt(link: PeerConnection, attempt: number): boolean {
    if (attempt !== this.attempt) {
      link.close();
      return false;
    }
    this.link = link;
    link.messages$.subscribe((data) => this.receive(data));
    link.closed$.subscribe(() => this.onClosed(link));
    link.opened.then(
      () => {
        this.ownOffers = [...this.players.rulesetOffers()];
        this.send({
          k: 'hello',
          v: NET_VERSION,
          id: this.playerId(),
          r: [...this.ownOffers],
        });
      },
      () => undefined
    );
    return true;
  }

  private receive(data: string): void {
    const message = parseNetMessage(data);
    if (message === null) {
      return;
    }
    if (message.k === 'hello') {
      this.peerState.set(message.id);
      this.peerOffers = message.r;
      this.greet(message.v);
      return;
    }
    if (!this.greeted) {
      return;
    }
    const { role } = this.lobby();
    switch (message.k) {
      case 'setup':
        if (role === 'guest') {
          this.events.next({ type: 'setup', setup: setupOf(message) });
        }
        return;
      case 'colors':
        if (role === 'host') {
          this.events.next({ type: 'colors', colors: message.colors });
        }
        return;
      case 'start':
        if (role === 'guest' && message.ruleset !== this.agreedRuleset()) {
          // A host that picks a ruleset both did not offer plays another game.
          this.endWith(this.attempt, { key: 'online.notices.otherVersion' });
          return;
        }
        if (role === 'guest') {
          this.match = message.n;
          this.lockstep = this.newLockstep(1);
          const start: OnlineStart = {
            ...setupOf(message),
            seed: message.seed,
            ruleset: message.ruleset,
          };
          this.pendingStart = { start, lockstep: this.lockstep };
          this.events.next({ type: 'start', start });
        }
        return;
      case 'in':
        if (message.n === this.match) {
          this.lockstep?.putRemote(message.t, message);
        }
        return;
      case 'sum':
        if (message.n === this.match) {
          this.lockstep?.putRemoteSum(message.t, message.h);
        }
        return;
      case 'bye':
        this.endWith(
          this.attempt,
          { key: 'online.notices.opponentLeft' },
          'left'
        );
        return;
    }
  }

  private greet(version: string): void {
    if (version !== NET_VERSION) {
      this.endWith(this.attempt, { key: 'online.notices.otherVersion' });
      return;
    }
    if (this.greeted) {
      return;
    }
    this.greeted = true;
    this.update({ phase: 'connected', notice: null });
    const { role, auto } = this.lobby();
    this.analytics.track('online_connected', {
      role: role ?? 'none',
      matchmade: auto,
    });
    this.events.next({
      type: 'connected',
      seat: role === 'host' ? 0 : 1,
      auto,
    });
  }

  private onClosed(link: PeerConnection): void {
    if (link === this.link) {
      this.endWith(this.attempt, { key: 'online.notices.lost' }, 'lost');
    }
  }

  private fail(attempt: number, error: unknown): void {
    console.warn('The online match could not connect', error);
    this.endWith(attempt, { key: 'online.notices.failed' });
  }

  /** Ends the attempt with a notice, telling the game if it was connected. */
  private endWith(
    attempt: number,
    notice: GameText,
    reason: OnlineEnd = 'lost'
  ): void {
    if (attempt !== this.attempt) {
      return;
    }
    this.analytics.track('online_ended', { reason, notice: notice.key });
    this.restart({ notice }, reason);
  }

  private newLockstep(seat: 0 | 1): Lockstep {
    const match = this.match;
    return new Lockstep(
      seat,
      (message) => {
        // A match that was replaced sends nothing more.
        if (match === this.match) {
          this.send(message);
        }
      },
      match
    );
  }

  private send(message: NetMessage): void {
    this.link?.send(JSON.stringify(message));
  }

  private update(change: Partial<OnlineLobby>): void {
    this.lobbyState.update((lobby) => ({ ...lobby, ...change }));
  }
}

function setupOf({ levelId, colors }: OnlineSetup): OnlineSetup {
  return { levelId, colors };
}

